using FunkoApiV._2.Entity;
using Microsoft.EntityFrameworkCore;

namespace FunkoApiV._2.Infrastructure;

public static class PostgresSchemaInitializer {
    public static Task EnsureSchemaAsync(AppDbContext db) =>
        db.Database.ExecuteSqlRawAsync(
            """
            CREATE TABLE IF NOT EXISTS "AspNetRoles" (
                "Id" bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
                "Name" character varying(256),
                "NormalizedName" character varying(256),
                "ConcurrencyStamp" text
            );

            CREATE TABLE IF NOT EXISTS "AspNetUsers" (
                "Id" bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
                "Nombre" text NOT NULL,
                "Apellido" text NOT NULL,
                "Createdt" timestamp with time zone NOT NULL,
                "UserName" character varying(256),
                "NormalizedUserName" character varying(256),
                "Email" character varying(256),
                "NormalizedEmail" character varying(256),
                "EmailConfirmed" boolean NOT NULL,
                "PasswordHash" text,
                "SecurityStamp" text,
                "ConcurrencyStamp" text,
                "PhoneNumber" text,
                "PhoneNumberConfirmed" boolean NOT NULL,
                "TwoFactorEnabled" boolean NOT NULL,
                "LockoutEnd" timestamp with time zone,
                "LockoutEnabled" boolean NOT NULL,
                "AccessFailedCount" integer NOT NULL
            );

            CREATE TABLE IF NOT EXISTS categoria (
                "Id" character varying(11) PRIMARY KEY,
                "Nombre" character varying(100) NOT NULL,
                "Descripcion" character varying(500),
                "CreatedAt" timestamp with time zone NOT NULL,
                "UpdatedAt" timestamp with time zone,
                "IsDeleted" boolean NOT NULL DEFAULT false
            );

            CREATE TABLE IF NOT EXISTS funko (
                "Id" bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
                "Name" character varying(20) NOT NULL,
                "Precio" numeric(20,2) NOT NULL,
                "Stock" integer NOT NULL,
                "Imagen" character varying(255),
                "CategoriaId" character varying(11) NOT NULL
                    REFERENCES categoria ("Id") ON DELETE RESTRICT,
                "ProveedorId" character varying(24) NOT NULL,
                "CreatedAt" timestamp with time zone NOT NULL,
                "UpdatedAt" timestamp with time zone,
                "IsDeleted" boolean NOT NULL DEFAULT false
            );

            CREATE TABLE IF NOT EXISTS "AspNetRoleClaims" (
                "Id" integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
                "RoleId" bigint NOT NULL REFERENCES "AspNetRoles" ("Id") ON DELETE CASCADE,
                "ClaimType" text,
                "ClaimValue" text
            );

            CREATE TABLE IF NOT EXISTS "AspNetUserClaims" (
                "Id" integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
                "UserId" bigint NOT NULL REFERENCES "AspNetUsers" ("Id") ON DELETE CASCADE,
                "ClaimType" text,
                "ClaimValue" text
            );

            CREATE TABLE IF NOT EXISTS "AspNetUserLogins" (
                "LoginProvider" text NOT NULL,
                "ProviderKey" text NOT NULL,
                "ProviderDisplayName" text,
                "UserId" bigint NOT NULL REFERENCES "AspNetUsers" ("Id") ON DELETE CASCADE,
                PRIMARY KEY ("LoginProvider", "ProviderKey")
            );

            CREATE TABLE IF NOT EXISTS "AspNetUserRoles" (
                "UserId" bigint NOT NULL REFERENCES "AspNetUsers" ("Id") ON DELETE CASCADE,
                "RoleId" bigint NOT NULL REFERENCES "AspNetRoles" ("Id") ON DELETE CASCADE,
                PRIMARY KEY ("UserId", "RoleId")
            );

            CREATE TABLE IF NOT EXISTS "AspNetUserTokens" (
                "UserId" bigint NOT NULL REFERENCES "AspNetUsers" ("Id") ON DELETE CASCADE,
                "LoginProvider" text NOT NULL,
                "Name" text NOT NULL,
                "Value" text,
                PRIMARY KEY ("UserId", "LoginProvider", "Name")
            );

            CREATE UNIQUE INDEX IF NOT EXISTS "RoleNameIndex"
                ON "AspNetRoles" ("NormalizedName");
            CREATE UNIQUE INDEX IF NOT EXISTS "UserNameIndex"
                ON "AspNetUsers" ("NormalizedUserName");
            CREATE INDEX IF NOT EXISTS "EmailIndex"
                ON "AspNetUsers" ("NormalizedEmail");
            CREATE INDEX IF NOT EXISTS "IX_AspNetRoleClaims_RoleId"
                ON "AspNetRoleClaims" ("RoleId");
            CREATE INDEX IF NOT EXISTS "IX_AspNetUserClaims_UserId"
                ON "AspNetUserClaims" ("UserId");
            CREATE INDEX IF NOT EXISTS "IX_AspNetUserLogins_UserId"
                ON "AspNetUserLogins" ("UserId");
            CREATE INDEX IF NOT EXISTS "IX_AspNetUserRoles_RoleId"
                ON "AspNetUserRoles" ("RoleId");
            CREATE INDEX IF NOT EXISTS "IX_funko_CategoriaId"
                ON funko ("CategoriaId");
            """);
}
